<script setup>
import{computed,nextTick,onBeforeUnmount,onMounted,ref,shallowRef}from'vue';
import{clockText,createStore,createWindowControl,emptyWindowSnapshot,historyPage,monthStats,recordTime,sceneStats,templates,validateConfig}from'./pomodoro-model.js';
import PomodoroIcon from'./PomodoroIcon.vue';import soundUrl from'./original/pomodoro-ding-BPamOesd.wav';
const props=defineProps({host:Object,initialSnapshot:Object,initialWindow:{type:Object,default:emptyWindowSnapshot},dedicated:Boolean,initialError:{type:String,default:''},initialPage:{type:String,default:'clock'}});
const snapshot=shallowRef(props.initialSnapshot),page=ref(props.initialPage),selected=ref(props.initialSnapshot.currentSceneId),choices=ref(templates.map(s=>s.id)),saving=ref(false),error=ref(''),uncertain=ref(false),draft=ref({}),configDraft=ref({...props.initialSnapshot.config}),editError=ref(''),editor=ref(),confirmation=ref(),selector=ref(),audio=ref(),pendingDelete=ref(null),dragged=ref(''),month=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1)),historyIndex=ref(1);
const sceneRevision=ref(props.initialSnapshot.revision),configRevision=ref(props.initialSnapshot.revision),deleteRevision=ref(props.initialSnapshot.revision),retryOperation=ref('');
const windowState=shallowRef(props.initialWindow),windowDraft=ref(props.initialWindow.config.enabled),windowRevision=ref(props.initialWindow.revision),windowSaving=ref(false),windowUncertain=ref(false),windowError=ref('');
const windowControl=createWindowControl(props.initialWindow,(method,args)=>props.host.request(method,args),{preview:props.host.preview,changed:value=>{windowState.value=value;}});
const progressEdge=computed(()=>({top:'bottom',bottom:'top',left:'right',right:'left'})[windowState.value.surface?.edge||'bottom']),progressVertical=computed(()=>['left','right'].includes(windowState.value.surface?.edge)),progressStyle=computed(()=>({'--v1797633e':'6px','--v88ca1360':({running:'rgb(255,170,0)',pause:'rgb(106,0,255)',stop:'rgb(0,119,255)',waiting:'rgb(0,119,255)'})[snapshot.value.phase.status]||'rgb(0,255,111)','--v720f4971':(snapshot.value.phase.status==='stop'?100:snapshot.value.progress)+'%'}));
let alive=true,timer,polling=false;
const store=createStore(props.initialSnapshot,(method,args)=>props.host.request(method,args),{preview:props.host.preview,changed:value=>{snapshot.value=value;}});
async function beforeLibrarySwitch(){await store.flush();await windowControl.flush();if(saving.value||uncertain.value||store.hasPending()||windowSaving.value||windowControl.hasPending())throw Error('上次操作结果未确定或仍在保存，请先重试');if([editor,confirmation,selector].some(dialog=>dialog.value?.open))throw Error('请先保存或关闭编辑窗口，再切换数据源');if(page.value==='pomodoro-settings'&&(JSON.stringify(configDraft.value)!==JSON.stringify(snapshot.value.config)||windowDraft.value!==windowState.value.config.enabled))throw Error('番茄设置尚未保存，请先保存配置或取消修改');return true;}
props.host.beforeLibrarySwitch=beforeLibrarySwitch;
const current=computed(()=>snapshot.value.scenes.find(s=>s.id===snapshot.value.currentSceneId)),scene=computed(()=>snapshot.value.scenes.find(s=>s.id===selected.value)||current.value),active=computed(()=>['running','pause','waiting','rest-pause'].includes(snapshot.value.phase.status)),stats=computed(()=>sceneStats(snapshot.value.history,scene.value?.id)),monthly=computed(()=>monthStats(snapshot.value.history,scene.value?.id,month.value)),history=computed(()=>historyPage(snapshot.value.history,scene.value?.id,historyIndex.value)),monthLabel=computed(()=>month.value.getFullYear()+'年'+(month.value.getMonth()+1)+'月'),canNext=computed(()=>month.value.getTime()<new Date(new Date().getFullYear(),new Date().getMonth(),1).getTime());
const stateLabel=computed(()=>({stop:'准备专注',running:'专注中',pause:'已暂停','rest-pause':'休息已暂停',waiting:'专注已结束',resting:'休息中'})[snapshot.value.phase.status]);
const notice=computed(()=>{const n=snapshot.value.notice;if(!n)return'';if(n.error)return n.error;if(n.notification==='unknown')return'上次完成提醒递送结果未确定';if(n.notification==='failed'||n.sound==='failed')return'完成提醒或声音调用失败';return'';});
async function refresh(){if(!alive||props.initialError||polling||saving.value||uncertain.value||page.value==='pomodoro-settings'||[editor,confirmation,selector].some(dialog=>dialog.value?.open))return;polling=true;try{await store.refresh();}catch(e){error.value='读取失败：'+String(e?.message||e);}finally{polling=false;}}
async function perform(operation,payload={}){if(saving.value||props.host.preview)return false;saving.value=true;error.value='';try{await store.change(operation,payload);uncertain.value=false;retryOperation.value='';return true;}catch(e){uncertain.value=store.hasPending();retryOperation.value=uncertain.value?operation:'';error.value='未更新：'+String(e?.message||e);return false;}finally{saving.value=false;}}
async function retry(){saving.value=true;try{await store.retry();if(retryOperation.value==='configure'){configDraft.value={...snapshot.value.config};configRevision.value=snapshot.value.revision;}retryOperation.value='';uncertain.value=false;error.value='';editor.value?.close();confirmation.value?.close();}catch(e){uncertain.value=store.hasPending();error.value='未更新：'+String(e?.message||e);}finally{saving.value=false;}}
async function initialize(skip=false){await perform('initialize',{templates:skip?[]:choices.value});}
async function openDetails(target){try{await props.host.request('view.openDetails',{page:target});}catch(e){error.value=String(e?.message||e);}}
function navigate(target){page.value=target;if(target==='pomodoro-settings'){configDraft.value={...snapshot.value.config};configRevision.value=snapshot.value.revision;windowDraft.value=windowState.value.config.enabled;windowRevision.value=windowState.value.revision;}}
async function refreshWindow(){if(!alive||props.host.preview||windowSaving.value)return;try{await windowControl.refresh();}catch(e){windowError.value='窗口状态读取失败：'+String(e?.message||e);}}
async function saveWindow(retry=false){if(windowSaving.value||props.host.preview)return;windowSaving.value=true;windowError.value='';try{if(retry)await windowControl.retry();else await windowControl.configure(windowDraft.value,windowRevision.value);windowDraft.value=windowState.value.config.enabled;windowRevision.value=windowState.value.revision;}catch(e){windowError.value='窗口设置未确认：'+String(e?.message||e);if(String(e?.message||e).startsWith('REVISION_CONFLICT:'))windowError.value+='；草稿已保留，请载入已保存设置后重新修改';}finally{windowUncertain.value=windowControl.hasPending();windowSaving.value=false;}}
async function stopUnavailableWindow(){windowDraft.value=false;await saveWindow();}
function reloadData(){if(!windowSaving.value&&!windowControl.hasPending())window.location.reload();}
async function reloadWindowDraft(){if(windowSaving.value||windowControl.hasPending())return;try{await windowControl.refresh();windowDraft.value=windowState.value.config.enabled;windowRevision.value=windowState.value.revision;windowError.value='';}catch(e){windowError.value='设置未载入：'+String(e?.message||e);}}
async function windowAction(action){try{await windowControl.action(action);windowError.value='';}catch(e){windowError.value=String(e?.message||e);}}
async function chooseScene(){if(props.dedicated){try{await props.host.request('pomodoro.window.menu');}catch(e){error.value=String(e?.message||e);}}else selector.value.showModal();}
function hover(inside){if(props.dedicated&&!props.host.preview)void props.host.request('pomodoro.window.hover',{inside}).catch(e=>{if(alive)error.value=String(e?.message||e);});}
function drag(event){if(props.dedicated&&!props.host.preview&&event.isTrusted&&event.button===0){event.preventDefault();void props.host.request('pomodoro.window.drag').catch(e=>{if(alive)error.value=String(e?.message||e);});}}
function windowEvent(event){if(!props.dedicated||event.source!==window.parent||event.origin!==new URLSearchParams(location.search).get('hostOrigin')||event.data?.type!=='souldesk:pomodoro-window')return;try{windowControl.surface(event.data.surface);}catch(e){windowError.value=String(e?.message||e);}}
function openScene(value){sceneRevision.value=snapshot.value.revision;draft.value=value?{id:value.id,name:value.name,icon:value.icon}:{id:crypto.randomUUID(),name:'',icon:'🔨'};editError.value='';editor.value.showModal();}
async function saveScene(){if(!draft.value.name?.trim()||[...draft.value.name].length>120||!draft.value.icon?.trim()||[...draft.value.icon].length>32){editError.value='未保存：请填写1～120字名称及场景图标';return;}if(await perform('scene.save',{scene:{...draft.value},expectedRevision:sceneRevision.value}))editor.value.close();else editError.value=error.value;}
async function saveConfig(){try{const config=validateConfig(configDraft.value);if(await perform('configure',{config,expectedRevision:configRevision.value})){configDraft.value={...snapshot.value.config};configRevision.value=snapshot.value.revision;}}catch(e){error.value='未保存：'+String(e?.message||e);}}
async function selectScene(id){if(await perform('select',{id}))selector.value?.close();}
function askDelete(type,id){deleteRevision.value=snapshot.value.revision;pendingDelete.value={type,id};confirmation.value.showModal();}
async function remove(){if(!pendingDelete.value)return;const{type,id}=pendingDelete.value;if(await perform(type==='scene'?'scene.delete':'history.delete',{id,expectedRevision:deleteRevision.value})){confirmation.value.close();pendingDelete.value=null;}}
async function reorder(from,to){const ids=snapshot.value.scenes.map(s=>s.id);if(from===to||!ids.includes(from)||!ids.includes(to))return;ids.splice(ids.indexOf(from),1);ids.splice(ids.indexOf(to),0,from);await perform('reorder',{ids});}
function showStats(id){selected.value=id;historyIndex.value=1;navigate('pomodoro-history');}
function changeMonth(delta){if(delta>0&&!canNext.value)return;month.value=new Date(month.value.getFullYear(),month.value.getMonth()+delta,1);}
async function previewSound(){try{audio.value.currentTime=0;await audio.value.play();}catch(e){error.value='提示音未播放：'+String(e?.message||e);}}
onBeforeUnmount(()=>{alive=false;clearInterval(timer);store.dispose();windowControl.dispose();window.removeEventListener('message',windowEvent);audio.value?.pause();if(props.host.beforeLibrarySwitch===beforeLibrarySwitch)props.host.beforeLibrarySwitch=undefined;});
onMounted(async()=>{if(props.dedicated)window.addEventListener('message',windowEvent);await props.host.ready();if(!alive||props.host.preview)return;if(!props.dedicated&&new URLSearchParams(location.search).get('verify')==='widgetjs'){try{if(page.value==='clock')await verifyClock();else await verifyDetails();}catch(e){error.value='隔离检查失败：'+String(e?.message||e);try{await saveVerification({failure:error.value,page:page.value});}catch{}}}if(alive)timer=setInterval(()=>{void refresh();if(props.initialError||props.dedicated||page.value==='pomodoro-settings')void refreshWindow();},1000);});
async function saveVerification(patch){const storage=await props.host.request('storage.get');await props.host.request('storage.set',{...storage,verification:{...storage.verification,...patch}});}
async function verifyDetails(){
 const storage=await props.host.request('storage.get');if(storage.verification?.detailsVerified)return;
 navigate('pomodoro-scenes');openScene();await nextTick();await saveScene();const invalid=editError.value.includes('未保存');draft.value.name='番茄'+props.host.instanceId.slice(0,8);draft.value.icon='📖';await nextTick();window.document.querySelector('#scene-form').requestSubmit();for(let n=0;n<100&&saving.value;n++)await new Promise(r=>setTimeout(r,40));if(editor.value.open)throw Error(editError.value||error.value||'场景未保存');
 const saved=snapshot.value.scenes.find(s=>s.name===draft.value.name);if(!saved)throw Error('场景缺失');await selectScene(saved.id);openScene();draft.value.name='临时场景';await saveScene();const extra=snapshot.value.scenes.find(s=>s.name==='临时场景');await reorder(extra.id,saved.id);const sorted=snapshot.value.scenes[0].id===extra.id;askDelete('scene',extra.id);await remove();
 navigate('pomodoro-settings');await nextTick();configDraft.value={pomoTime:5,shortBreakTime:1,isAutoNext:false,isSoundEnabled:false};window.document.querySelector('#config-form').requestSubmit();for(let n=0;n<100&&saving.value;n++)await new Promise(r=>setTimeout(r,40));const configured=snapshot.value.config.pomoTime===5&&!snapshot.value.config.isSoundEnabled;
 showStats(saved.id);await nextTick();const before=monthLabel.value;window.document.querySelector('[data-action="previous-month"]').click();await nextTick();const monthChanged=monthLabel.value!==before;changeMonth(1);
 await saveVerification({detailsVerified:invalid&&sorted&&configured&&monthChanged,invalidSaveRejected:invalid,savedLabel:saved.name,sceneId:saved.id,config:snapshot.value.config,detailsPageVerified:window.document.querySelector('.month-chart')!==null&&window.document.querySelector('.history-list')!==null});
}
async function verifyClock(){
 let storage=await props.host.request('storage.get'),prior=storage.verification;
 if(!prior?.uiVerified){if(!snapshot.value.initialized)await initialize(true);await openDetails('pomodoro-scenes');for(let n=0;n<160;n++){storage=await props.host.request('storage.get');if(storage.verification?.detailsVerified)break;await new Promise(r=>setTimeout(r,50));}if(!storage.verification?.detailsVerified)throw Error('详情窗口未完成检查');await store.refresh();await nextTick();window.document.querySelector('[data-action="start"]').click();for(let n=0;n<100&&saving.value;n++)await new Promise(r=>setTimeout(r,30));const running=snapshot.value.phase.status==='running';await nextTick();window.document.querySelector('[data-action="pause"]').click();for(let n=0;n<100&&saving.value;n++)await new Promise(r=>setTimeout(r,30));const paused=snapshot.value.phase.status==='pause';await perform('start');const resumed=snapshot.value.phase.status==='running';await perform('reset');await saveVerification({actionsVerified:running&&paused&&resumed&&snapshot.value.phase.status==='stop'});}
 await store.refresh();await nextTick();await window.document.fonts.load('48px Rubik');const style=getComputedStyle(window.document.querySelector('.pomodoro')),fontLoaded=window.document.fonts.check('48px Rubik'),stylesLoaded=style.borderRadius==='22px'&&getComputedStyle(window.document.querySelector('.time')).fontSize==='48px';
 if(audio.value.readyState<1)await Promise.race([new Promise(r=>audio.value.addEventListener('loadedmetadata',r,{once:true})),new Promise(r=>setTimeout(r,1200))]);storage=await props.host.request('storage.get');const result=storage.verification||{},retained=snapshot.value.currentSceneId===result.sceneId&&snapshot.value.scenes.some(s=>s.name===result.savedLabel)&&JSON.stringify(snapshot.value.config)===JSON.stringify(result.config),soundLoaded=audio.value.readyState>=1&&Number.isFinite(audio.value.duration);
 await saveVerification({runtimeLoads:(result.runtimeLoads||0)+1,uiVerified:result.detailsVerified===true&&result.detailsPageVerified===true&&result.actionsVerified===true&&retained&&fontLoaded&&soundLoaded,stylesLoaded,fontLoaded,soundLoaded,retained,remainingSeconds:snapshot.value.remainingSeconds});
}
</script>
<template>
 <main v-if="initialError" class="pomodoro-unavailable"><p role="alert">计时数据暂不可用：{{initialError}}</p><p>专用窗开关仍可单独关闭。</p><button :disabled="host.preview||windowSaving||windowUncertain||!windowState.config.enabled" @click="stopUnavailableWindow">停用专用番茄窗</button><button :disabled="host.preview||windowSaving||windowUncertain" @click="reloadData">重新读取计时数据</button><p role="status">{{windowState.config.enabled?'专用窗仍启用':'专用窗已停用'}}<template v-if="windowState.nativeCleanupPending"> · 正在确认资源释放</template></p><p v-if="windowError||windowState.nativeError" role="status">{{windowError||windowState.nativeError}}</p><button v-if="windowUncertain" :disabled="windowSaving" @click="saveWindow(true)">重试原保存</button><button v-else :disabled="host.preview||windowSaving" @click="reloadWindowDraft">载入已保存设置</button></main>
 <div v-else-if="page==='clock'" :class="['pomodoro-root',{'dedicated':dedicated}]" @mouseenter="hover(true)" @mouseleave="hover(false)">
  <section :class="['pomodoro',snapshot.phase.status,{'resting':snapshot.phase.status==='rest-pause'}]" :aria-label="stateLabel">
   <button class="clock-menu" title="番茄钟设置" @click="openDetails('pomodoro-settings')" :disabled="host.preview">⋯</button>
   <button v-if="dedicated" type="button" class="pomodoro-drag-handle" title="拖动番茄钟" aria-label="拖动番茄钟" :disabled="host.preview" @pointerdown="drag"><PomodoroIcon name="grip" :size="16"/></button>
   <template v-if="current"><button class="scene" :disabled="active||saving||uncertain" @click="chooseScene"><span>{{current.icon}}</span> {{['resting','rest-pause'].includes(snapshot.phase.status)?stateLabel:current.name}}<PomodoroIcon v-if="!active" name="chevron-right" :size="14"/></button><div class="time rubik-regular" :title="stateLabel">{{clockText(snapshot.remainingSeconds)}}</div>
    <div class="buttons"><button v-if="['stop','pause','resting','rest-pause'].includes(snapshot.phase.status)" class="btn start" :title="snapshot.phase.status==='rest-pause'?'继续休息':'开始或继续专注'" :aria-label="snapshot.phase.status==='rest-pause'?'继续休息':'开始或继续专注'" data-action="start" :disabled="saving||uncertain||host.preview" @click="perform('start')"><PomodoroIcon name="play"/></button><button v-if="snapshot.phase.status==='running'" class="btn small" title="暂停" aria-label="暂停" data-action="pause" :disabled="saving||uncertain" @click="perform('pause')"><PomodoroIcon name="pause"/></button><button v-if="snapshot.phase.status!=='stop'" class="btn small" title="结束专注或休息" aria-label="结束专注或休息" :disabled="saving||uncertain" @click="perform('finish')"><PomodoroIcon name="check"/></button></div>
   </template>
   <button v-else-if="snapshot.initialized||dedicated" class="add-scene-btn" :disabled="host.preview" @click="openDetails('pomodoro-scenes')"><PomodoroIcon name="plus"/>添加场景</button><div v-else class="time rubik-regular">30:00</div>
  </section>
  <div v-if="dedicated&&windowState.surface&&!windowState.surface.expanded" :class="['progress',progressEdge]" :style="progressStyle" aria-label="专注阶段进度"><div :class="['pomodoro-progress-bar',{vertical:progressVertical}]"><div :class="['outer',{vertical:progressVertical}]"></div><div :class="['inner',{vertical:progressVertical}]"></div></div></div>
  <div v-if="!snapshot.initialized&&!dedicated" class="initial-choices"><strong>选择初始场景</strong><label v-for="item in templates" :key="item.id"><input type="checkbox" v-model="choices" :value="item.id" :disabled="saving||uncertain"/>{{item.icon}} {{item.name}}</label><div><button :disabled="saving||uncertain||host.preview" @click="initialize(true)">跳过</button><button :disabled="saving||uncertain||host.preview" @click="initialize()">确定</button></div></div>
  <p v-if="error||windowError||windowState.nativeError||notice||snapshot.message" class="clock-message" role="status">{{error||windowError||windowState.nativeError||notice||snapshot.message}}<button v-if="uncertain" @click="retry" :disabled="saving">重试</button></p>
 </div>
 <main v-else class="pomodoro-details">
  <header><h1>番茄钟</h1><nav><button :class="{chosen:page==='pomodoro-scenes'}" @click="navigate('pomodoro-scenes')">专注场景</button><button :class="{chosen:page==='pomodoro-history'}" @click="navigate('pomodoro-history')">统计与历史</button><button :class="{chosen:page==='pomodoro-settings'}" @click="navigate('pomodoro-settings')">设置</button></nav></header>
  <p v-if="error||notice||snapshot.message" class="operation-message" role="status">{{error||notice||snapshot.message}}<button v-if="uncertain" @click="retry" :disabled="saving">重试原操作</button></p>
  <section v-if="page==='pomodoro-scenes'"><div class="section-heading"><h2>专注场景</h2><button class="primary" :disabled="saving||uncertain||host.preview" @click="openScene()"><PomodoroIcon name="plus"/>添加场景</button></div><p v-if="!snapshot.scenes.length" class="empty">添加一个场景，开始记录你的专注。</p><ul class="scene-list"><li v-for="item in snapshot.scenes" :key="item.id" :draggable="!saving&&!uncertain" @dragstart="dragged=item.id" @dragover.prevent @drop.prevent="reorder(dragged,item.id)"><button class="scene-stat" @click="showStats(item.id)"><span class="scene-icon">{{item.icon}}</span><span>{{item.name}}<small>{{sceneStats(snapshot.history,item.id).totalHours}}小时</small></span></button><span v-if="item.id===snapshot.currentSceneId" class="current-mark">当前</span><button :disabled="active||saving||uncertain||host.preview" @click="selectScene(item.id)">使用</button><button :disabled="saving||uncertain||host.preview" @click="openScene(item)">编辑</button><button :disabled="saving||uncertain||host.preview" @click="askDelete('scene',item.id)">删除</button></li></ul><p class="hint">拖动场景可调整顺序。专注结束或重置后可切换场景。</p></section>
  <section v-else-if="page==='pomodoro-settings'"><h2>番茄钟设置</h2><form id="config-form" @submit.prevent="saveConfig"><fieldset :disabled="saving||uncertain||host.preview"><label>专注时长（分钟）<input type="number" min="5" max="60" step="1" v-model.number="configDraft.pomoTime" required/></label><label>短休息时长（分钟）<input type="number" min="1" max="30" step="1" v-model.number="configDraft.shortBreakTime" required/></label><label class="check-label"><input type="checkbox" v-model="configDraft.isAutoNext"/>休息结束后自动开始下一轮</label><label class="check-label"><input type="checkbox" v-model="configDraft.isSoundEnabled"/>启用完成提示音<button type="button" @click="previewSound">试听</button></label><button class="primary" type="submit">{{saving?'保存中…':'保存设置'}}</button></fieldset></form><div class="window-settings"><h3>专用番茄窗</h3><p class="hint">固定150×150、置顶、拖动贴边及独立托盘；移出两秒收起并保留进度条。默认关闭，此开关只控制当前实例的专用窗。</p><form @submit.prevent="saveWindow()"><fieldset :disabled="windowSaving||windowUncertain||host.preview"><label class="check-label"><input type="checkbox" v-model="windowDraft"/>启用专用番茄窗</label><button type="submit">{{windowSaving?'保存中…':'保存专用窗设置'}}</button><button type="button" @click="reloadWindowDraft">载入已保存设置</button></fieldset></form><p class="hint" role="status">{{windowState.config.enabled?'已启用':'未启用'}}<template v-if="windowState.nativeCleanupPending"> · 正在确认资源释放</template><template v-else-if="windowState.config.enabled"> · {{windowState.surface?.nativeSettled?'窗口状态已确认':'等待窗口状态确认'}}</template></p><p v-if="windowError||windowState.nativeError" class="operation-message" role="status">{{windowError||windowState.nativeError}}<button v-if="windowUncertain" :disabled="windowSaving" @click="saveWindow(true)">重试原保存</button></p><div class="window-actions"><button :disabled="host.preview||windowSaving||windowUncertain||!windowState.config.enabled" @click="windowAction('open')">打开专用窗</button><button :disabled="host.preview||windowSaving||windowUncertain||!windowState.surface" @click="windowAction('hide')">隐藏专用窗</button><button :disabled="host.preview||windowSaving||windowUncertain||!windowState.surface" @click="windowAction('reset')">重置位置</button></div><p class="hint">隐藏或关闭专用窗保留当前计时；停用开关释放专用窗和托盘，原卡片及计时继续。</p></div></section>
  <section v-else><div class="section-heading"><h2>{{scene?.icon}} {{scene?.name||'专注统计'}}</h2><select v-if="snapshot.scenes.length" v-model="selected" aria-label="统计场景" @change="historyIndex=1"><option v-for="item in snapshot.scenes" :value="item.id" :key="item.id">{{item.name}}</option></select></div><div class="statistics"><div><strong>{{stats.totalHours}}</strong><span>累计时长（小时）</span></div><div><strong>{{stats.checkInDays}}</strong><span>打卡天数</span></div><div><strong>{{stats.count}}</strong><span>专注次数</span></div></div><div class="section-heading"><h3>本月专注 · {{monthLabel}}</h3><div><button data-action="previous-month" aria-label="上个月" @click="changeMonth(-1)">‹</button><button aria-label="下个月" :disabled="!canNext" @click="changeMonth(1)">›</button></div></div><div class="month-summary">共{{monthly.totalMinutes}}分钟 · {{monthly.checkInDays}}天 · 最长单日{{monthly.maxMinutes}}分钟</div><div class="month-chart" role="img" :aria-label="monthLabel+'每日专注分钟数'"><div v-for="day in monthly.days" :key="day.date" class="day-column" :title="day.date+'：'+day.minutes+'分钟'"><div class="bar-track"><span :style="{height:(day.minutes?Math.max(2,day.minutes/Math.max(1,monthly.maxMinutes)*100):0)+'%'}"></span></div><small>{{day.day}}</small></div></div><h3>历史记录</h3><ul class="history-list"><li v-for="record in history.items" :key="record.id"><span>{{recordTime(record.startTime)}}</span><strong>{{Math.ceil(record.duration/60)}}分钟</strong><button :disabled="saving||uncertain||host.preview" @click="askDelete('history',record.id)">删除</button></li><li v-if="!history.items.length" class="empty">暂无专注记录</li></ul><div class="pagination"><button :disabled="history.page===1" @click="historyIndex=history.page-1">上一页</button><span>第{{history.page}} / {{history.pages}}页 · {{history.total}}条</span><button :disabled="history.page===history.pages" @click="historyIndex=history.page+1">下一页</button></div></section>
 </main>
 <dialog ref="selector" class="scene-selector"><h2>选择场景</h2><button v-for="item in snapshot.scenes" :key="item.id" :disabled="saving||uncertain||host.preview" @click="selectScene(item.id)">{{item.icon}} {{item.name}}</button><button @click="selector.close()">关闭</button><button :disabled="host.preview" @click="selector.close();openDetails('pomodoro-scenes')">管理场景</button></dialog>
 <dialog ref="editor"><h2>{{snapshot.scenes.some(s=>s.id===draft.id)?'编辑场景':'添加场景'}}</h2><form id="scene-form" novalidate @submit.prevent="saveScene"><fieldset :disabled="saving||uncertain"><label>图标<input v-model="draft.icon" maxlength="32" aria-label="场景图标"/></label><label>场景名称<input v-model="draft.name" maxlength="120" aria-label="场景名称"/></label><p class="operation-message" role="status">{{editError}}</p><div class="dialog-actions"><button type="button" @click="editor.close()">取消</button><button type="submit" class="primary">保存场景</button></div></fieldset></form></dialog>
 <dialog ref="confirmation"><h2>删除{{pendingDelete?.type==='scene'?'场景':'记录'}}？</h2><p v-if="pendingDelete?.type==='scene'">同时删除该场景的{{snapshot.history.filter(h=>h.sceneId===pendingDelete.id).length}}条专注记录。</p><p v-else>删除后将重新计算累计时长和打卡统计。</p><p>若已连接共享库，删除场景或记录会同步影响全部连接实例。</p><p class="operation-message">{{error}}</p><div class="dialog-actions"><button :disabled="saving||uncertain" @click="confirmation.close()">取消</button><button :disabled="saving||uncertain" @click="remove">确认删除</button></div></dialog>
 <audio ref="audio" :src="soundUrl" preload="metadata"></audio>
</template>
